                                    &lt;button type="submit" style="border: none; background: none; padding: 0; cursor: pointer;"&gt;
                                        &lt;img src="{{ asset('assets/img/delete.svg') }}" alt="Eliminar" title="Eliminar"&gt;
                                    &lt;/button&gt;
                                &lt;/form&gt;
