if (preg_match_all($patron, $texto, $coincidencias)) {
    echo "Números encontrados:&lt;br&gt;";
    foreach ($coincidencias[0] as $num) {
        echo $num . "&lt;br&gt;";
    }
}
?&gt;
</code></pre> <pre><code>&lt;?php
